__NUXT_JSONP__("/tw/stay", (function(a,b,c,d,e,f,g,h,i,j){return {data:[{details:{slug:"tw",pageTitle:"住宿 | Mentor Language Institute",pageDescription:"MLI與USSS合作，為MLI的學生提供住宿信息 ",title:"住宿",subtitle:["MLI與USSS合作，為MLI的學生提供住宿信息 \u003Cbr \u002F\u003E有關更多詳細信息，請訪問 \u003Ca href=\"www.usssinc.net\u002Ftw\" target=\"_blank\"\u003Ewww.usssinc.net\u002Ftw\u003C\u002Fa\u003E"],image:"\u002Fimages\u002Flocation\u002Faccommodations\u002Faccommodation-1.jpg",gallery:["\u002Fimages\u002Flocation\u002Faccommodations\u002Faccommodation-2.jpg","\u002Fimages\u002Flocation\u002Faccommodations\u002Faccommodation-3.jpg"],note:"學生可選擇寄宿家庭或是宿舍。",types:[{title:"宿舍",description:["我們宿舍提供40個房間。有許多能和其他國際學生交流的機會。如果您有預算考量，我們建議您選擇宿舍。"],lists:["\u003Cb\u003E房間\u003C\u002Fb\u003E : 私人 (獨立)、合住 (2人) 及 合住 (4 people)","\u003Cb\u003E供餐\u003C\u002Fb\u003E : 不提供餐 (有完整廚房可使用)","\u003Cb\u003E隱私\u003C\u002Fb\u003E : 寄養家庭較多隱私空間。宿舍有一些規則。","\u003Cb\u003E通勤\u003C\u002Fb\u003E : 大約二十分鐘步行或是公車時間。"],gallery:["\u002Fimages\u002Flocation\u002Faccommodations\u002Fdormitory-1.jpg","\u002Fimages\u002Flocation\u002Faccommodations\u002Fdormitory-2.jpg","\u002Fimages\u002Flocation\u002Faccommodations\u002Fdormitory-3.jpg","\u002Fimages\u002Flocation\u002Faccommodations\u002Fdormitory-4.jpg"],prices:[{title:"宿舍費用",table:{tableMaxCol:4,title:"安置費用* : $200\u003Cbr \u002F\u003E 如果未滿 18 歲，租金將比 18 歲以上的人高出約 10%。",thead:[b,c,"合住","合住(四人)"],tbody:[[d,a,a,a],[e,"$550","$410",a],[f,"$1,100","$820","$600"],[g,"$1,650","$1,230","$900"],[h,"$2,200","$1,640","$1,200"],[i,"$4,160","$2,960","$2,160"],[j,"$6,240","$4,440","$3,240"]]},notes:["*安置費用需一次性繳交。不可退還。\u003Cbr \u002F\u003E**保證金將在學生搬出後退還。"]}]},{title:"寄宿家庭",description:["選擇寄宿家庭的學生在尋找一個能夠練習英語的, 且具有美国特色的傳統的家庭。"],lists:["\u003Cb\u003E房間\u003C\u002Fb\u003E : 私人 (獨立)","\u003Cb\u003E供餐\u003C\u002Fb\u003E : 每天兩餐(早餐及晚餐)","\u003Cb\u003E隱私\u003C\u002Fb\u003E : 每個家庭有不同的規則。","\u003Cb\u003E通勤\u003C\u002Fb\u003E : 公車30- 45分鐘"],gallery:["\u002Fimages\u002Flocation\u002Faccommodations\u002Fhomestay-1.jpg","\u002Fimages\u002Flocation\u002Faccommodations\u002Fhomestay-2.jpg","\u002Fimages\u002Flocation\u002Faccommodations\u002Fhomestay-3.jpg","\u002Fimages\u002Flocation\u002Faccommodations\u002Fhomestay-4.jpg"],prices:[{title:"寄宿家庭費用",table:{tableMaxCol:3,title:"安置費用* : $300\u003Cbr \u002F\u003E 如果未滿 18 歲，租金將比 18 歲以上的人高出約 10%。",thead:[b,c,"合住***"],tbody:[[d,a,a],[e,"$436","$384"],[f,"$872","$768"],[g,"$1,308","$1,152"],[h,"$1,744","$1,536"],[i,"$3,160","$2,904"],[j,"$4,740","$4,356"]]},notes:["*安置費用需一次性繳交。不可退還。\u003Cbr \u002F\u003E**保證金將在學生搬出後退還。\u003Cbr \u002F\u003E***您如果申請寄宿家庭的合住房間，您需要和另一個人一起申請。"]}]}],comments:{title:"管理人員的提醒",description:["當您一開始到達美國的時候，不是很容易可以找到住的地方，特別是那些沒有社會安全號碼(SSN)也沒有信任歷史的國際學生。\u003Cbr \u002F\u003E大多數的地方需要SSN及信用歷史才能租房。\u003Cbr \u002F\u003E因此，我們建議首先至少幾個月的時間住在我們的宿舍。","※您的住宿將由 U.S. Support Service Inc.或是其它仲介提供。"]},dir:"\u002Fstay",path:"\u002Fstay\u002Ftw",extension:".json",createdAt:"2026-10-22T16:31:31.116Z",updatedAt:"2025-05-26T12:06:27.922Z"}}],fetch:{},mutations:void 0}}("$300","","私人","\u003Cb\u003E保證金**\u003C\u002Fb\u003E","1週","2週","3週","4週","8週","12週")));